insert into public.knowledge_articles
    (id, title, content, source_title, source_url, keywords, active)
values
('20000000-0000-4000-8000-000000000001', 'Как оформить отпуск', 'В демо-прототипе для заявки на отпуск откройте раздел «Заявки», выберите тип «Отпуск», укажите дату начала и окончания, при необходимости добавьте комментарий и отправьте заявку. Дата окончания не должна предшествовать дате начала. Сумма для отпуска не указывается. После отправки заявка получает статус pending и ожидает рассмотрения руководителем сотрудника или HR. Одобрение фиксирует решение в прототипе: оно не списывает отпускные дни и не оформляет документ в 1С или Documentolog. Правила о сроке подачи, праздничных днях, пересечении отпусков и количестве положенных дней в демонстрационной базе не определены; их нужно уточнить у HR.', 'Демо: оформление заявки на отпуск', null, array['отпуск', 'отпуска', 'заявка', 'заявку', 'оформить', 'даты']::text[], true),
('20000000-0000-4000-8000-000000000002', 'Как запросить аванс', 'В демо-прототипе для заявки на аванс откройте раздел «Заявки», выберите тип «Аванс», укажите положительную сумму и при необходимости комментарий. Даты отпуска не заполняются. После отправки заявка ожидает решения руководителя сотрудника или HR; решение можно посмотреть в карточке заявки. Одобрение заявки в прототипе не выполняет банковский перевод. Демонстрационная база не устанавливает валюту, график выплат, долю зарплаты для аванса или срок перечисления. По этим вопросам обратитесь в HR.', 'Демо: оформление заявки на аванс', null, array['аванс', 'аванса', 'запросить', 'сумма', 'заявка']::text[], true),
('20000000-0000-4000-8000-000000000003', 'Кто видит кадровые данные', 'В демо-прототипе сотрудник видит свой профиль и свои заявки. Руководитель дополнительно видит профили и заявки прямых подчинённых. HR/администратор имеет доступ ко всем профилям и заявкам в рамках своей роли. Личные уведомления доступны только их получателю. Роль определяется сервером по профилю сотрудника, связанному с учётной записью. Текст сообщения AI Jana или выбранная кнопка в интерфейсе не дают дополнительных прав. AI Jana в этом этапе отвечает по общей демонстрационной базе знаний и не читает персональные профили, заявки или зарплаты работников.', 'Демо: роли и доступ к данным', null, array['доступ', 'роль', 'роли', 'данные', 'кадровые', 'руководитель', 'видит']::text[], true),
('20000000-0000-4000-8000-000000000004', 'Где посмотреть статус заявки', 'В демо-прототипе откройте раздел «Мои заявки» или «Заявки» и выберите нужную карточку. Pending означает, что заявка ожидает рассмотрения, approved — одобрена, rejected — отклонена, cancelled — отозвана сотрудником. В карточке заявки отображается комментарий руководителя или HR, рассмотревшего заявку, если он указан. При изменении статуса создаётся уведомление для сотрудника. Срок рассмотрения демонстрационная база не устанавливает. AI Jana объясняет значения статусов, но не получает текущий статус вашей конкретной заявки: проверьте его в карточке.', 'Демо: статусы заявок', null, array['статус', 'статусы', 'заявки', 'посмотреть', 'pending', 'approved', 'rejected', 'cancelled']::text[], true),
('20000000-0000-4000-8000-000000000005', 'Где посмотреть остаток отпуска', 'В демо-прототипе остаток отпускных дней отображается в личном профиле. Это демонстрационный снимок кадровых данных, доступный только для чтения. AI Jana не вычисляет персональный остаток и не запрашивает его из профиля. Если значение требует уточнения, обратитесь в HR. Одобрение заявки на отпуск не изменяет этот остаток автоматически; синхронизация с 1С:ЗУП относится к будущей интеграции.', 'Демо: остаток отпускных дней', null, array['остаток', 'отпускных', 'дней', 'профиль', 'посмотреть']::text[], true),
('20000000-0000-4000-8000-000000000006', 'Как исправить сведения в профиле', 'В демо-прототипе официальные сведения профиля — имя, компания, должность, подразделение, руководитель, дата приёма и остаток отпуска — доступны сотруднику только для чтения. Для исправления обратитесь в HR; AI Jana не изменяет эти данные. Регистрация создаёт учётную запись, но не создаёт кадровый профиль и не назначает роль. Администратор должен создать или связать профиль с учётной записью. Если после входа получен отказ из-за отсутствия HR-профиля, обратитесь к администратору проекта.', 'Демо: кадровый профиль и привязка учётной записи', null, array['профиль', 'исправить', 'изменить', 'должность', 'регистрация', 'привязка']::text[], true),
('20000000-0000-4000-8000-000000000007', 'Где найти назначенное обучение', 'В демо-прототипе откройте Jana Academy, чтобы увидеть каталог и назначенные вам курсы. Курс назначает HR или руководитель сотрудника. Назначенный курс содержит учебный материал и тест. Сотрудник может открыть материал назначенного ему активного курса; присутствие курса в каталоге само по себе не означает, что он назначен. О назначении создаётся уведомление. AI Jana объясняет порядок работы, но не назначает курсы.', 'Демо: назначения Jana Academy', null, array['обучение', 'назначенный', 'назначенные', 'курс', 'курсы', 'academy']::text[], true),
('20000000-0000-4000-8000-000000000008', 'Как пройти курс и увидеть результат', 'В демо-прототипе откройте назначенный курс, изучите материал и ответьте на все вопросы теста. Пока курс не завершён, можно сохранять прогресс от 0 до 99 процентов. После отправки допустимого набора ответов сервер рассчитывает процент правильных ответов, сохраняет результат и отмечает курс завершённым с прогрессом 100 процентов. Завершение и успешная сдача — разные понятия: отдельный проходной балл в текущем прототипе не установлен. Правильные ответы не передаются в карточке курса. Правила пересдач демонстрационная база не устанавливает.', 'Демо: прогресс и результат обучения', null, array['курс', 'прогресс', 'тест', 'результат', 'обучение', 'завершить']::text[], true),
('20000000-0000-4000-8000-000000000009', 'Где читать уведомления', 'В демо-прототипе уведомления отображаются в отдельном разделе платформы. Сотруднику приходит уведомление об изменении статуса заявки и о назначении курса. Руководитель получает уведомление о завершении обучения прямым подчинённым. Уведомление можно отметить прочитанным. Пользователь получает только свои уведомления; роль HR не открывает чужой личный список уведомлений. Доставка по электронной почте, SMS или мессенджерам в этом прототипе не реализована.', 'Демо: центр уведомлений', null, array['уведомления', 'уведомление', 'прочитать', 'прочитанным']::text[], true),
('20000000-0000-4000-8000-000000000010', 'Что умеет AI Jana и когда обращаться в HR', 'AI Jana помогает найти информацию в общей демонстрационной базе знаний и показывает найденные источники. Каждый вопрос обрабатывается отдельно; история диалога не передаётся на сервер. Ассистент не принимает кадровые решения, не одобряет заявки, не изменяет профили и не получает персональные сведения работников. Не передавайте в чат пароли, токены и реальные персональные данные. Если надёжной информации нет, следует обратиться в HR через принятый в вашей команде канал. Предложение обратиться в HR не создаёт обращение автоматически; адрес, телефон и срок ответа в демонстрационной базе не заданы.', 'Демо: границы AI Jana', null, array['jana', 'ассистент', 'помощник', 'источники', 'hr', 'умеет']::text[], true),
('20000000-0000-4000-8000-000000000011', 'Как перенести отпуск в Google Calendar', 'В демо-прототипе файл календаря доступен для одобренной заявки на отпуск. Скачайте файл .ics в карточке заявки. На компьютере откройте Google Calendar → Настройки → Импорт и экспорт, выберите файл и календарь, затем нажмите «Импортировать». Даты берутся из одобренной заявки; последний день отпуска включён. Файл не добавляет событие автоматически и не синхронизирует дальнейшие изменения: при изменении или отмене отпуска обновите событие вручную. Даты обучения в текущем прототипе не заданы, поэтому экспорт курсов пока недоступен.', 'Демо: экспорт отпуска в календарь', null, array['календарь', 'google', 'ics', 'отпуск', 'импорт']::text[], true)
