-- Generated by scripts/export_jana_demo.py from knowledge_base/demo/articles.json.
-- DEMO DATA ONLY, not approved Jana Post HR policy.
-- Apply to a demo database after 0001_digital_hr.sql and seed.sql (if used).
-- Reuses the first three demo IDs; other articles are not deleted.
begin;
set local standard_conforming_strings = on;
on conflict (id) do update set
    title = excluded.title, content = excluded.content,
    source_title = excluded.source_title, source_url = excluded.source_url,
    keywords = excluded.keywords, active = excluded.active;
commit;
